import { test } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { LockfileError, parseLockfile } from '../src/services/lockfileParser.js';

// Real lockfiles generated by npm in the demo folders (never hand-written).
const demoLockfile = (name) =>
  fs.readFileSync(path.join(import.meta.dirname, '../../demo', name, 'package-lock.json'), 'utf8');

function lockfile(packages, lockfileVersion = 3) {
  return JSON.stringify({ name: 'app', lockfileVersion, packages });
}

function find(result, name, version) {
  return result.dependencies.find((dep) => dep.name === name && (!version || dep.version === version));
}

test('reads a real npm 7+ lockfile', () => {
  const result = parseLockfile(demoLockfile('vibe-store'));

  assert.equal(result.lockfileVersion, 3);
  assert.equal(result.packageCount, result.dependencies.length);
  assert.deepEqual(find(result, 'lodash'), { name: 'lodash', version: '4.17.15', isDev: false, isDirect: true });
  assert.deepEqual(find(result, 'minimist', '1.2.5'), { name: 'minimist', version: '1.2.5', isDev: true, isDirect: true });
  assert.equal(find(result, 'body-parser').isDirect, false, 'installed by express, not directly');
});

test('names come from the last node_modules/ segment, including scopes and nesting', () => {
  const result = parseLockfile(
    lockfile({
      '': { dependencies: { a: '1.0.0', '@scope/pkg': '2.0.0' } },
      'node_modules/a': { version: '1.0.0' },
      'node_modules/a/node_modules/b': { version: '3.0.0' },
      'node_modules/@scope/pkg': { version: '2.0.0' },
      'node_modules/@scope/pkg/node_modules/@other/deep': { version: '4.0.0' },
    }),
  );

  assert.deepEqual(
    result.dependencies.map(({ name, version, isDirect }) => [name, version, isDirect]),
    [
      ['@other/deep', '4.0.0', false],
      ['@scope/pkg', '2.0.0', true],
      ['a', '1.0.0', true],
      ['b', '3.0.0', false],
    ],
  );
});

test('only dev: true is development-only; devOptional counts as production', () => {
  const result = parseLockfile(
    lockfile({
      '': {},
      'node_modules/watcher': { version: '1.0.0', dev: true },
      'node_modules/fsevents': { version: '2.0.0', devOptional: true },
    }),
  );

  assert.equal(find(result, 'watcher').isDev, true);
  assert.equal(find(result, 'fsevents').isDev, false);
});

test('keeps each distinct name and version once, as production if any copy is', () => {
  const result = parseLockfile(
    lockfile({
      '': { dependencies: { a: '1' } },
      'node_modules/a': { version: '1.0.0' },
      'node_modules/a/node_modules/ms': { version: '2.0.0' },
      'node_modules/tool/node_modules/ms': { version: '2.0.0', dev: true },
      'node_modules/ms': { version: '2.1.3', dev: true },
    }),
  );

  const ms = result.dependencies.filter((dep) => dep.name === 'ms');
  assert.deepEqual(ms, [
    { name: 'ms', version: '2.0.0', isDev: false, isDirect: false },
    { name: 'ms', version: '2.1.3', isDev: true, isDirect: false },
  ]);
});

test('skips the root, workspace folders and links', () => {
  const result = parseLockfile(
    lockfile({
      '': { name: 'app', version: '1.0.0' },
      'packages/web': { version: '0.0.1' },
      'node_modules/web': { resolved: 'packages/web', link: true },
      'node_modules/real': { version: '1.0.0' },
    }),
  );

  assert.deepEqual(result.dependencies.map((dep) => dep.name), ['real']);
});

test('lockfile version 2 is accepted', () => {
  assert.equal(parseLockfile(lockfile({ '': {} }, 2)).lockfileVersion, 2);
});

function assertRejects(text, code, messagePattern) {
  assert.throws(
    () => parseLockfile(text),
    (error) => error instanceof LockfileError && error.code === code && messagePattern.test(error.message),
  );
}

test('explains how to fix a lockfile from npm 6 or older', () => {
  assertRejects(
    JSON.stringify({ lockfileVersion: 1, dependencies: {} }),
    'LOCKFILE_V1',
    /npm 6 or older\. Run `npm install` with npm 7 or newer/,
  );
});

test('rejects invalid JSON, such as a yarn.lock', () => {
  assertRejects('# yarn lockfile v1\nlodash@^4:\n  version "4.17.21"', 'LOCKFILE_INVALID_JSON', /not valid JSON/);
});

test('rejects a lockfile without a packages section', () => {
  assertRejects(JSON.stringify({ lockfileVersion: 3 }), 'LOCKFILE_NO_PACKAGES', /no "packages" section/);
});

test('rejects JSON that is not a lockfile at all', () => {
  assertRejects('[1, 2, 3]', 'LOCKFILE_NOT_NPM', /does not look like/);
  assertRejects(JSON.stringify({ name: 'app' }), 'LOCKFILE_UNSUPPORTED_VERSION', /lockfile version/);
});

test('rejects files over 5 MB with a 413', () => {
  const huge = lockfile({ '': {}, 'node_modules/a': { version: '1.0.0', padding: 'x'.repeat(5 * 1024 * 1024) } });

  assert.throws(
    () => parseLockfile(huge),
    (error) => error.code === 'LOCKFILE_TOO_LARGE' && error.status === 413,
  );
});
